def now_ts() -> float:
    return time.time()


def iso(ts: float | None) -> str | None:
    return dt.datetime.fromtimestamp(ts).astimezone().isoformat(timespec="seconds") if ts is not None else None


def day_bounds(day: str) -> tuple[float, float]:
    d = dt.date.fromisoformat(day)
    start = dt.datetime.combine(d, dt.time.min).astimezone().timestamp()
    end = dt.datetime.combine(d + dt.timedelta(days=1), dt.time.min).astimezone().timestamp()
    return start, end


class ClosingConnection(sqlite3.Connection):
    def __exit__(self, exc_type: Any, exc_value: Any, traceback: Any) -> Any:
        try:
            return super().__exit__(exc_type, exc_value, traceback)
        finally:
            self.close()


def conn() -> sqlite3.Connection:
    c = sqlite3.connect(DB_PATH, timeout=8, factory=ClosingConnection)
    c.row_factory = sqlite3.Row
    c.execute("PRAGMA journal_mode=WAL")
    c.execute("PRAGMA busy_timeout=8000")
    return c


def copy_to_local_cache(source: Path, destination: Path) -> None:
    """Copy through ordinary reads/writes, avoiding macOS fcopyfile deadlocks."""
    destination.parent.mkdir(parents=True, exist_ok=True)
    temporary = destination.with_name(destination.name + f".{threading.get_ident()}.tmp")
    last_error: OSError | None = None
    for attempt in range(12):
        source_fd = target_fd = None
        try:
            source_fd = os.open(source, os.O_RDONLY)
            target_fd = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
            while True:
                chunk = os.read(source_fd, 1024 * 1024)
                if not chunk:
                    break
                view = memoryview(chunk)
                while view:
                    written = os.write(target_fd, view)
                    view = view[written:]
            os.fsync(target_fd)
            os.close(target_fd)
            target_fd = None
            os.close(source_fd)
            source_fd = None
            temporary.replace(destination)
            return
        except OSError as exc:
            last_error = exc
            temporary.unlink(missing_ok=True)
        finally:
            if target_fd is not None:
                os.close(target_fd)
            if source_fd is not None:
                os.close(source_fd)
        # File Provider may transiently reject reads; retry from the start.
        time.sleep(min(1.0, 0.15 * (attempt + 1)))
    raise OSError(str(last_error) if last_error else f"无法读取本机文件：{source.name}")


def init_db() -> None:
    with DB_LOCK, conn() as c:
        c.executescript("""
        CREATE TABLE IF NOT EXISTS activities (
            id INTEGER PRIMARY KEY, fingerprint TEXT UNIQUE NOT NULL,
            start REAL NOT NULL, end REAL NOT NULL,
            app TEXT NOT NULL DEFAULT '', window_title TEXT NOT NULL DEFAULT '',
            page_title TEXT NOT NULL DEFAULT '', url TEXT NOT NULL DEFAULT '',
            incognito INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT '',
            source TEXT NOT NULL, raw_json TEXT NOT NULL DEFAULT '{}'
        );
        CREATE INDEX IF NOT EXISTS idx_activities_start ON activities(start);
        CREATE INDEX IF NOT EXISTS idx_activities_app_start ON activities(app,start);
        CREATE TABLE IF NOT EXISTS captures (
            id INTEGER PRIMARY KEY, captured_at REAL NOT NULL, activity_id INTEGER,
            app TEXT NOT NULL, window_title TEXT NOT NULL DEFAULT '',
            path TEXT NOT NULL, sha256 TEXT NOT NULL, ocr_text TEXT NOT NULL DEFAULT '',
            FOREIGN KEY(activity_id) REFERENCES activities(id) ON DELETE SET NULL
        );
        CREATE UNIQUE INDEX IF NOT EXISTS idx_captures_hash ON captures(sha256);
        CREATE INDEX IF NOT EXISTS idx_captures_time ON captures(captured_at);
        CREATE TABLE IF NOT EXISTS reports (
            day TEXT PRIMARY KEY, generated_at REAL NOT NULL, model TEXT NOT NULL,
            report_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ready', error TEXT NOT NULL DEFAULT ''
        );
        CREATE TABLE IF NOT EXISTS memory_observations (
            id INTEGER PRIMARY KEY, observed_at REAL NOT NULL, activity_id INTEGER,
            app TEXT NOT NULL DEFAULT '', window_title TEXT NOT NULL DEFAULT '',
            image_hash TEXT NOT NULL DEFAULT '', ocr_text TEXT NOT NULL DEFAULT '',
            vision_text TEXT NOT NULL DEFAULT '',
            FOREIGN KEY(activity_id) REFERENCES activities(id) ON DELETE SET NULL
        );
        CREATE INDEX IF NOT EXISTS idx_memory_observations_time ON memory_observations(observed_at);
        CREATE TABLE IF NOT EXISTS hourly_memories (
            day TEXT NOT NULL, hour INTEGER NOT NULL, start REAL NOT NULL, end REAL NOT NULL,
            model TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'ready',
            error TEXT NOT NULL DEFAULT '', updated_at REAL NOT NULL,
            PRIMARY KEY(day,hour)
        );
        CREATE TABLE IF NOT EXISTS chat_threads (
            id INTEGER PRIMARY KEY, scope TEXT NOT NULL CHECK(scope IN ('work','life')),
            title TEXT NOT NULL DEFAULT '', created_at REAL NOT NULL, updated_at REAL NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_chat_threads_scope_updated ON chat_threads(scope,updated_at DESC);
        CREATE TABLE IF NOT EXISTS chat_messages (
            id INTEGER PRIMARY KEY, thread_id INTEGER NOT NULL, role TEXT NOT NULL CHECK(role IN ('user','assistant')),
            content TEXT NOT NULL DEFAULT '', evidence_ids_json TEXT NOT NULL DEFAULT '[]',
            status TEXT NOT NULL DEFAULT 'ready', error TEXT NOT NULL DEFAULT '',
            context_start TEXT NOT NULL DEFAULT '', context_end TEXT NOT NULL DEFAULT '', created_at REAL NOT NULL,
            FOREIGN KEY(thread_id) REFERENCES chat_threads(id) ON DELETE CASCADE
        );
        CREATE INDEX IF NOT EXISTS idx_chat_messages_thread_created ON chat_messages(thread_id,created_at,id);
        CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
        """)
        # Keep OCR evidence after the original image expires; hashes are only a short-term dedupe aid.
        c.execute("DROP INDEX IF EXISTS idx_captures_hash")
        c.execute("CREATE INDEX IF NOT EXISTS idx_captures_hash ON captures(sha256,captured_at)")
        for key, value in DEFAULT_SETTINGS.items():
            c.execute("INSERT OR IGNORE INTO settings(key,value_json) VALUES(?,?)", (key, json.dumps(value, ensure_ascii=False)))


def migrate_legacy_capture_paths() -> None:
    """Keep screenshot rows pointing at files after migrating the data folder."""
    legacy = Path.home() / "Library/Application Support/LocalMind/screenshots"
    if legacy.resolve() == SCREENSHOTS.resolve():
        return
    with DB_LOCK, conn() as c:
        rows = c.execute("SELECT id,path FROM captures WHERE path IS NOT NULL").fetchall()
        for row in rows:
            try:
                relative = Path(row["path"]).relative_to(legacy)
            except ValueError:
                continue
            destination = SCREENSHOTS / relative
            if destination.is_file():
                c.execute("UPDATE captures SET path=? WHERE id=?", (str(destination), row["id"]))


def load_settings() -> dict[str, Any]:
    with SETTINGS_LOCK, conn() as c:
        vals = {r["key"]: json.loads(r["value_json"]) for r in c.execute("SELECT key,value_json FROM settings")}
    return {**DEFAULT_SETTINGS, **vals}


def save_settings(changes: dict[str, Any]) -> dict[str, Any]:
    allowed = {"capture_enabled", "capture_interval_seconds", "retention_days", "excluded_apps", "excluded_domains", "ollama_model", "ollama_url", "auto_report_time", "memory_enabled", "vision_model", "vision_interval_seconds"}
    clean = {k: v for k, v in changes.items() if k in allowed}
    if "capture_interval_seconds" in clean:
        clean["capture_interval_seconds"] = max(10, min(3600, int(clean["capture_interval_seconds"])))
    if "retention_days" in clean:
        clean["retention_days"] = max(1, min(365, int(clean["retention_days"])))
    if "vision_interval_seconds" in clean:
        clean["vision_interval_seconds"] = max(60, min(3600, int(clean["vision_interval_seconds"])))
    if "memory_enabled" in clean:
        clean["memory_enabled"] = bool(clean["memory_enabled"])
    for key in ("excluded_apps", "excluded_domains"):
        if key in clean:
            if not isinstance(clean[key], list):
                raise ValueError(f"{key} 必须是列表")
            clean[key] = [str(x).strip() for x in clean[key] if str(x).strip()][:200]
    if "ollama_model" in clean:
        clean["ollama_model"] = str(clean["ollama_model"]).strip()[:100]
    if "vision_model" in clean:
        clean["vision_model"] = str(clean["vision_model"]).strip()[:100]
    if "ollama_url" in clean:
        clean["ollama_url"] = local_url(str(clean["ollama_url"]).strip())
    if "auto_report_time" in clean and not re.fullmatch(r"\d\d:\d\d", str(clean["auto_report_time"])):
        raise ValueError("自动日报时间格式应为 HH:MM")
    with SETTINGS_LOCK, conn() as c:
        for k, v in clean.items():
            c.execute("INSERT INTO settings(key,value_json) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value_json=excluded.value_json", (k, json.dumps(v, ensure_ascii=False)))
    return load_settings()


def local_url(url: str) -> str:
    parsed = urllib.parse.urlparse(url)
    host = (parsed.hostname or "").lower()
    if parsed.scheme != "http" or host not in {"127.0.0.1", "localhost", "::1"}:
        raise ValueError("Ollama 地址只允许本机 HTTP 服务")
    return url.rstrip("/")


def request_json(url: str, method: str = "GET", body: dict[str, Any] | None = None, timeout: float = 3) -> Any:
    data = json.dumps(body, ensure_ascii=False).encode() if body is not None else None
    req = urllib.request.Request(url, data=data, method=method, headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read())


def fetch_aw_buckets() -> dict[str, Any]:
    return request_json(f"{AW_URL}/api/0/buckets/", timeout=2)


def parse_time(value: str) -> float | None:
    try:
        return dt.datetime.fromisoformat(value.replace("Z", "+00:00")).timestamp()
    except (TypeError, ValueError):
        return None


def event_window(event: dict[str, Any]) -> tuple[float, float] | None:
    start = parse_time(event.get("timestamp", ""))
    if start is None:
        return None
    try:
        duration = max(0.0, float(event.get("duration", 0)))
    except (TypeError, ValueError):
        duration = 0.0
    return start, start + duration


def import_aw_events(days_back: float = 0.08) -> dict[str, Any]:
    """Read and upsert ActivityWatch events without touching its backing store."""
    start = now_ts() - days_back * 86400
    buckets = fetch_aw_buckets()
    fetched: list[tuple[str,str,dict[str,Any]]] = []
    query: dict[str,Any] = {"end":iso(now_ts()),"limit":-1 if days_back>1 else 500}
    if days_back>1:
        query["start"]=iso(start)
    for bucket_id, bucket in buckets.items():
        bid = str(bucket_id).lower()
        btype = str(bucket.get("type", "")).lower()
        if not any(x in bid or x in btype for x in ("watcher-window", "watcher-afk", "watcher-web")):
            continue
        params = urllib.parse.urlencode(query)
        events = request_json(f"{AW_URL}/api/0/buckets/{urllib.parse.quote(bucket_id, safe='')}/events?{params}", timeout=5)
        source = "web" if "watcher-web" in bid or "watcher-web" in btype else "afk" if "watcher-afk" in bid or "watcher-afk" in btype else "window"
        fetched.extend((source,bucket_id,event) for event in (events if isinstance(events,list) else []))
    private_web=[]
    for source,_,event in fetched:
        interval=event_window(event)
        if source=="web" and interval and bool((event.get("data") or {}).get("incognito",False)):
            private_web.append(interval)
    added=0
    with DB_LOCK, conn() as c:
        for source,bucket_id,event in fetched:
            interval = event_window(event)
            if not interval:
                continue
            t0, t1 = interval
            data = event.get("data") or {}
            app = str(data.get("app", data.get("application", "")) or "")
            title = str(data.get("title", data.get("window_title", "")) or "")
            url = str(data.get("url", "") or "")
            status = str(data.get("status", "") or "")
            if source=="web" and bool(data.get("incognito",False)):
                continue
            if source=="window":
                low=f"{app} {title}".casefold()
                browser=any(x in low for x in ("chrome","safari","firefox","edge","brave","arc","opera"))
                private_title=any(x in low for x in ("incognito","private browsing","无痕","隐私浏览"))
                private_overlap=browser and any((max(t0,a)<min(t1,b)) or (a==b and t0<=a<=t1) for a,b in private_web)
                if private_title or private_overlap:
                    continue
            raw = json.dumps({"bucket": bucket_id, "data": data}, ensure_ascii=False, sort_keys=True)
            fp = hashlib.sha256(f"{bucket_id}|{event.get('timestamp')}|{raw}".encode()).hexdigest()
            cur = c.execute("""INSERT OR IGNORE INTO activities(fingerprint,start,end,app,window_title,page_title,url,incognito,status,source,raw_json)
                VALUES(?,?,?,?,?,?,?,?,?,?,?)""", (fp,t0,t1,app,title,str(data.get("title", "") or ""),url,int(bool(data.get("incognito", False))),status,source,raw))
            added += cur.rowcount
            if cur.rowcount == 0:
                c.execute("UPDATE activities SET end=MAX(end,?) WHERE fingerprint=?",(t1,fp))
    return {"buckets": len(buckets), "imported": added}


def helper_call(*args: str, timeout: float = 25) -> dict[str, Any]:
    if not HELPER.exists():
        raise RuntimeError("Swift 截图工具尚未编译；运行 scripts/install.sh 或查看 README")
    proc = subprocess.run([str(HELPER), *args], capture_output=True, text=True, timeout=timeout)
    try:
        result = json.loads(proc.stdout.strip().splitlines()[-1])
    except Exception:
        raise RuntimeError((proc.stderr or proc.stdout or "截图工具没有返回状态").strip()[:800])
    if result.get("error"):
        raise RuntimeError(result["error"])
    return result


def current_activity(ts: float | None = None) -> sqlite3.Row | None:
    ts = ts or now_ts()
    with conn() as c:
        rows = c.execute("SELECT * FROM activities WHERE source IN ('window','afk','web') AND start<=? AND end>=? ORDER BY start DESC LIMIT 120", (ts + 2, ts - 25)).fetchall()
    return next((r for r in rows if r["source"] == "window"), None)


def current_web(ts: float | None = None) -> sqlite3.Row | None:
    ts = ts or now_ts()
    with conn() as c:
        return c.execute("SELECT * FROM activities WHERE source='web' AND start<=? AND end>=? ORDER BY start DESC LIMIT 1", (ts + 2, ts - 45)).fetchone()


def is_excluded(app: str, title: str, domain: str, settings: dict[str, Any]) -> bool:
    hay = f"{app} {title}".casefold()
    if any(item.casefold() in hay for item in settings["excluded_apps"]):
        return True
    if any(x in title.casefold() for x in ("private browsing", "incognito", "无痕", "隐私浏览")):
        return True
    domain = domain.lower().split(":")[0].split("/")[0].rstrip(".")
    for item in settings["excluded_domains"]:
        rule = str(item).lower().strip().lstrip(".")
        if not rule:
            continue
        if domain == rule or domain.endswith("." + rule) or ("." not in rule and rule in domain):
            return True
    return False


def eligible_capture_context(settings: dict[str, Any]) -> tuple[sqlite3.Row, dict[str, Any], str] | dict[str, str]:
    aw = current_activity()
    if aw is None:
        raise RuntimeError("ActivityWatch 当前没有可确认的前台应用记录；为保护隐私，本次不截图")
    # AFK data can overlap the most recent active window and has priority.
    ts = now_ts()
    with conn() as c:
        afk = c.execute("SELECT status FROM activities WHERE source='afk' AND start<=? AND end>=? ORDER BY start DESC LIMIT 1", (ts + 2, ts - 30)).fetchone()
    if afk and afk["status"].lower() not in {"not-afk", "active", ""}:
        return {"skipped": "电脑处于空闲状态"}
    native = helper_call("status")
    app = native.get("app", "")
    title = native.get("title", "")
    if is_excluded(app, title, "", settings):
        return {"skipped": "前台应用位于排除清单"}
    if aw["app"] and not (aw["app"].casefold() in app.casefold() or app.casefold() in aw["app"].casefold()):
        raise RuntimeError("ActivityWatch 与 macOS 前台应用不一致；为保护隐私，本次不截图")
    web = current_web()
    is_browser = any(x in (app + " " + (aw["app"] or "")).casefold() for x in ("chrome", "safari", "firefox", "edge", "brave", "arc", "opera"))
    domain = ""
    if is_browser:
        if not web or not web["url"] or web["incognito"]:
            return {"skipped": "浏览器页面地址不可用或处于无痕窗口"}
        parsed = urllib.parse.urlparse(web["url"])
        if parsed.scheme not in {"http", "https"} or not parsed.hostname:
            return {"skipped": "浏览器页面地址无法确认"}
        domain = parsed.hostname
        if is_excluded(app, title, domain, settings):
            return {"skipped": "当前网页位于敏感域名排除清单"}
    return aw, native, domain


def collect_screenshot() -> dict[str, Any]:
    settings = load_settings()
    if not settings["capture_enabled"]:
        return {"skipped": "截图采集已暂停"}
    context = eligible_capture_context(settings)
    if isinstance(context, dict): return context
    aw, native, _domain = context
    app, title = native.get("app", ""), native.get("title", "")
    ts = now_ts()
    filename = f"{int(ts)}-{threading.get_ident()}.jpg"
    path = SCREENSHOTS / filename
    cache_temp = IMAGE_CACHE / f"capture-pending-{filename}"
    try:
        # Capture into a persistent local cache first. macOS may evict the
        # visible Documents archive through File Provider, which can make even
        # the local image endpoint fail with EDEADLK when it tries to read it.
        cache_temp.parent.mkdir(parents=True, exist_ok=True)
        result = helper_call("capture", str(cache_temp))
    except Exception:
        path.unlink(missing_ok=True)
        cache_temp.unlink(missing_ok=True)
        raise
    stored_path = Path(str(result.get("path") or cache_temp))
    digest, ocr = result.get("sha256", ""), str(result.get("ocrText", ""))
    if not stored_path.is_file() or not digest:
        cache_temp.unlink(missing_ok=True)
        raise RuntimeError("截图或 SHA-256 校验未成功")
    # Exact image and near-identical OCR repeats are dropped before retaining the image.
    with conn() as c:
        exact = c.execute("SELECT id FROM captures WHERE sha256=? AND captured_at>=?", (digest,ts-86400)).fetchone()
        prior = c.execute("SELECT captured_at,ocr_text FROM captures ORDER BY captured_at DESC LIMIT 1").fetchone()
    normalized = re.sub(r"\s+", "", ocr).casefold()
    prior_norm = re.sub(r"\s+", "", prior["ocr_text"] or "").casefold() if prior else ""
    similar = prior and ts - prior["captured_at"] < max(60, settings["capture_interval_seconds"] * 2) and normalized and prior_norm and SequenceMatcher(None, normalized[:2000], prior_norm[:2000]).ratio() >= 0.96
    if exact or similar:
        path.unlink(missing_ok=True)
        stored_path.unlink(missing_ok=True)
        cache_temp.unlink(missing_ok=True)
        return {"skipped": "与上一条截图相同或 OCR 内容重复"}
    if not normalized:
        path.unlink(missing_ok=True)
        stored_path.unlink(missing_ok=True)
        cache_temp.unlink(missing_ok=True)
        return {"skipped": "截图未识别到文字"}
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        copy_to_local_cache(stored_path, path)
        stored_path = path
    except OSError:
        # Keep the local copy as the record source if the archive provider is
        # temporarily unavailable; image access remains local and reliable.
        logger.exception("screenshot archive write failed; retaining local copy")
    stored_cache = cache_temp
    with DB_LOCK, conn() as c:
        cur = c.execute("INSERT INTO captures(captured_at,activity_id,app,window_title,path,sha256,ocr_text) VALUES(?,?,?,?,?,?,?)",
                        (ts, aw["id"], app, title, str(stored_path), digest, ocr[:30000]))
        capture_id = int(cur.lastrowid)
    stable_cache = IMAGE_CACHE / f"capture-{capture_id}.jpg"
    try:
        if stored_cache.is_file():
            copy_to_local_cache(stored_cache, stable_cache)
            if stored_path == stored_cache:
                with DB_LOCK, conn() as c:
                    c.execute("UPDATE captures SET path=? WHERE id=?", (str(stable_cache), capture_id))
            stored_cache.unlink(missing_ok=True)
    except OSError:
        logger.exception("could not retain local screenshot cache id=%s", capture_id)
    return {"captured": True, "activity_id": aw["id"], "bytes": result.get("bytes", 0), "characters": len(ocr)}


def normalize_ocr(value: str) -> str:
    return re.sub(r"\s+", "", value).casefold()[:6000]


def analyze_visual(path: Path, observation_id: int, settings: dict[str, Any]) -> None:
    """Use a small local vision model on a single changed frame, then discard it."""
    begin = time.monotonic()
    resized_path = path.with_name(path.stem + "-vl.jpg")
    try:
        # Cap visual tokens on Retina/high-resolution displays. OCR is retained
        # from the original full-resolution frame separately.
        resize = subprocess.run(["/usr/bin/sips", "-Z", "960", str(path), "--out", str(resized_path)],
                                capture_output=True, text=True, timeout=15)
        image_path = resized_path if resize.returncode == 0 and resized_path.is_file() else path
        image = base64.b64encode(image_path.read_bytes()).decode("ascii")
        body = {"model": settings["vision_model"], "stream": False, "keep_alive": 0,
                "messages": [{"role": "user", "content": "请用中文简短描述这张电脑前台窗口截图里正在进行的任务和重要界面状态。只描述图中可见事实；不要复述大段文字，不推测用户意图。最多 80 字。", "images": [image]}],
                "options": {"temperature": 0.1, "num_ctx": 8192, "num_predict": 120}}
        with OLLAMA_LOCK:
            response = request_json(local_url(settings["ollama_url"]) + "/api/chat", "POST", body, timeout=90)
        text = re.sub(r"\s+", " ", str((response.get("message") or {}).get("content", ""))).strip()[:500]
        if text:
            with DB_LOCK, conn() as c:
                c.execute("UPDATE memory_observations SET vision_text=? WHERE id=?", (text, observation_id))
            LAST_ERROR.pop("vision", None)
        logger.info("vision_sample elapsed=%.2fs observation=%s chars=%d", time.monotonic()-begin, observation_id, len(text))
    except Exception as exc:
        LAST_ERROR["vision"] = str(exc)[:500]
        logger.warning("vision_sample failed observation=%s error=%s", observation_id, exc)
    finally:
        resized_path.unlink(missing_ok=True)
        path.unlink(missing_ok=True)


def collect_memory_observation() -> dict[str, Any]:
    global VISION_LAST_TS
    settings = load_settings()
    if not settings["capture_enabled"] or not settings["memory_enabled"]:
        return {"skipped": "记忆采集已暂停"}
    context = eligible_capture_context(settings)
    if isinstance(context, dict): return context
    activity, native, _domain = context
    ts = now_ts()
    path = VISION_TMP / f"{int(ts * 1000)}-{threading.get_ident()}.jpg"
    try:
        result = helper_call("capture", str(path), timeout=8)
        ocr = str(result.get("ocrText", ""))[:4000]
        digest = str(result.get("sha256", ""))
        if not path.is_file() or not digest:
            raise RuntimeError("临时截图或哈希校验失败")
        app, title = str(native.get("app", "")), str(native.get("title", ""))
        normalized = normalize_ocr(ocr)
        with DB_LOCK, conn() as c:
            previous = c.execute("SELECT id,app,window_title,image_hash,ocr_text,observed_at FROM memory_observations ORDER BY observed_at DESC LIMIT 1").fetchone()
            same_context = previous and previous["app"] == app and previous["window_title"] == title
            same_text = same_context and normalized and SequenceMatcher(None, normalized[:2500], normalize_ocr(previous["ocr_text"])[:2500]).ratio() >= 0.985
            same_blank = same_context and not normalized and previous["image_hash"] == digest
            visual_interval = max(60, int(settings["vision_interval_seconds"]))
            should_describe = time.monotonic() - VISION_LAST_TS >= visual_interval
            if same_blank or (same_text and not should_describe):
                path.unlink(missing_ok=True)
                return {"skipped": "画面文字与上下文未变化"}
            if same_context and not normalized and not should_describe and ts - previous["observed_at"] < 15:
                path.unlink(missing_ok=True)
                return {"skipped": "无文字画面采样间隔内未到"}
            cur = c.execute("INSERT INTO memory_observations(observed_at,activity_id,app,window_title,image_hash,ocr_text) VALUES(?,?,?,?,?,?)",
                            (ts, activity["id"], app, title, digest, ocr))
            observation_id = int(cur.lastrowid)
        now = time.monotonic()
        should_describe = now - VISION_LAST_TS >= visual_interval
        if should_describe:
            VISION_LAST_TS = now
            threading.Thread(target=analyze_visual, args=(path, observation_id, settings), daemon=True, name="localmind-vision").start()
        else:
            path.unlink(missing_ok=True)
        return {"observed": True, "observation_id": observation_id, "ocr_characters": len(ocr), "vision_queued": should_describe}
    except Exception:
        path.unlink(missing_ok=True)
        raise


MEMORY_SCHEMA = {"type":"object", "properties":{"memory":{"type":"string","maxLength":1800}}, "required":["memory"], "additionalProperties":False}


def generate_hourly_memory(day: str, hour: int) -> None:
    start = dt.datetime.fromisoformat(day).replace(hour=hour).astimezone().timestamp()
    end = start + 3600
    with MEMORY_LOCK:
        with DB_LOCK, conn() as c:
            rows = c.execute("SELECT observed_at,activity_id,app,window_title,ocr_text,vision_text FROM memory_observations WHERE observed_at>=? AND observed_at<? ORDER BY observed_at LIMIT 600", (start,end)).fetchall()
            c.execute("INSERT INTO hourly_memories(day,hour,start,end,model,content,status,error,updated_at) VALUES(?,?,?,?,?,'','generating','',?) ON CONFLICT(day,hour) DO UPDATE SET status='generating',error='',updated_at=excluded.updated_at",
                      (day,hour,start,end,load_settings()["ollama_model"],now_ts()))
        try:
            if not rows:
                with DB_LOCK, conn() as c:
                    c.execute("UPDATE hourly_memories SET status='empty',content='',updated_at=? WHERE day=? AND hour=?", (now_ts(),day,hour))
                return
            evidence = []
            for row in rows:
                item = {"time": dt.datetime.fromtimestamp(row["observed_at"]).astimezone().strftime("%H:%M:%S"),
                        "app": row["app"], "window": row["window_title"],
                        "ocr": re.sub(r"\s+", " ", row["ocr_text"])[:300], "visual": row["vision_text"][:150]}
                evidence.append(item)
            if len(evidence) > 50:
                step = (len(evidence)-1) / 49
                evidence = [evidence[round(i*step)] for i in range(50)]
            settings = load_settings()
            prompt = ("请根据下列本机屏幕观察记录，写一份中文小时记忆，按时间顺序概括实际做过的工作/活动和可确认的结果；尽量保留时间段、应用和主题。\n"
                      "严格区分事实与推断；相同内容合并；忽略密码、令牌等敏感文本；不要补充记录中没有的信息。"
                      "若证据不足，明确写‘记录有限’。控制在 5 条以内。\n\n" + json.dumps(evidence,ensure_ascii=False))
            generated = ollama_generate(prompt, MEMORY_SCHEMA, settings, timeout=300)
            content = str(generated.get("memory", "")).strip()[:1800]
            if not content: raise RuntimeError("本机模型没有返回小时记忆")
            with DB_LOCK, conn() as c:
                c.execute("UPDATE hourly_memories SET model=?,content=?,status='ready',error='',updated_at=? WHERE day=? AND hour=?",
                          (settings["ollama_model"],content,now_ts(),day,hour))
            write_daily_memory(day)
            with DB_LOCK, conn() as c:
                c.execute("DELETE FROM memory_observations WHERE observed_at>=? AND observed_at<?", (start,end))
            logger.info("hourly_memory day=%s hour=%02d observations=%d elapsed_model=done",day,hour,len(rows))
        except Exception as exc:
            with DB_LOCK, conn() as c:
                c.execute("UPDATE hourly_memories SET status='error',error=?,updated_at=? WHERE day=? AND hour=?", (str(exc)[:500],now_ts(),day,hour))
            LAST_ERROR["memory"] = str(exc)[:500]
            logger.exception("hourly memory generation failed day=%s hour=%02d",day,hour)


def write_daily_memory(day: str) -> None:
    with DB_LOCK, conn() as c:
        rows = c.execute("SELECT hour,content,status FROM hourly_memories WHERE day=? AND status='ready' ORDER BY hour", (day,)).fetchall()
    lines = [f"# LocalMind 当日记忆 · {day}", "", "以下内容由本机活动记录归纳；请通过时间线和截图核对具体事实。", ""]
    for row in rows:
        lines.extend([f"## {row['hour']:02d}:00–{row['hour']:02d}:59", "", row["content"], ""])
    path = MEMORIES / f"{day}.md"
    temporary = path.with_suffix(".md.tmp")
    temporary.write_text("\n".join(lines), encoding="utf-8")
    temporary.replace(path)


def cleanup_memories() -> int:
    cutoff_ts = now_ts() - 30 * 86400
    cutoff_day = dt.datetime.fromtimestamp(cutoff_ts).astimezone().date().isoformat()
    removed = 0
    with DB_LOCK, conn() as c:
        removed = c.execute("DELETE FROM hourly_memories WHERE day<?", (cutoff_day,)).rowcount
        c.execute("DELETE FROM memory_observations WHERE observed_at<?", (cutoff_ts,))
    for path in MEMORIES.glob("*.md"):
        if path.stem < cutoff_day:
            path.unlink(missing_ok=True)
    for path in VISION_TMP.iterdir():
        try:
            if path.is_file() and path.stat().st_mtime < now_ts() - 3600: path.unlink(missing_ok=True)
        except OSError: pass
    return removed


def cleanup_screenshots() -> int:
    cutoff = now_ts() - int(load_settings()["retention_days"]) * 86400
    removed = 0
    with DB_LOCK, conn() as c:
        rows = c.execute("SELECT id,path FROM captures WHERE captured_at<?", (cutoff,)).fetchall()
        for row in rows:
            if row["path"]:
                Path(row["path"]).unlink(missing_ok=True)
            (IMAGE_CACHE / f"capture-{row['id']}.jpg").unlink(missing_ok=True)
            c.execute("UPDATE captures SET path='' WHERE id=?", (row["id"],))
            removed += 1
    return removed


